+  background: transparent;
+  align-items: center;
+  justify-content: center;
+  padding: 0;
+  cursor: pointer;
+}
+
+.menu-btn:focus-visible{
+  outline: 2px solid color-mix(in srgb, var(--accent) 55%, transparent);
+  outline-offset: 3px;
+}
+
+.menu-icon{
+  width: 18px;
+  height: 18px;
+  display: grid;
+  gap: 5px;
+}
+.menu-icon span{
+  height: 1.5px;
+  background: var(--text);
+  border-radius: 2px;
+  transition: transform 220ms ease, opacity 220ms ease;
+}
+
+/* Overlay menu */
+.overlay{
+  position: fixed;
+  inset: 0;
+  z-index: 60;
+  background: var(--bg);
+  display: grid;
+  place-items: center;
