+
+.overlay-nav{
+  display: grid;
+  gap: 16px;
+  font-family: var(--serif);
+  font-size: clamp(34px, 6vw, 56px);
+  line-height: 1.05;
+  letter-spacing: -0.02em;
+}
+
+.overlay-meta{
+  margin-top: 18px;
+  color: var(--muted);
+  font-size: 14px;
+}
+
+/* Sections */
+section{
+  padding: clamp(56px, 7.2vw, 120px) 0;
+}
+
+.hero{
+  padding-top: clamp(56px, 9vw, 140px);
+}
+
+.hero-grid{
+  display: grid;
+  grid-template-columns: 1.2fr 0.8fr;
+  gap: clamp(18px, 3.2vw, 44px);
+  align-items: end;
+}
+
+.hero-aside{
+  border-left: 1px solid var(--hairline);
+  padding-left: clamp(16px, 2.4vw, 28px);
+}
+
+.media{
+  display: grid;
+  grid-template-columns: 1.2fr 0.9fr 0.9fr;
+  gap: clamp(12px, 2vw, 22px);
