+  position: sticky;
+  top: 110px;
+}
+
+.quote{
+  font-family: var(--serif);
+  font-size: 26px;
+  line-height: 1.15;
+  letter-spacing: -0.01em;
+  margin: 0;
+}
+
+/* Contact */
+.contact-hero{
+  min-height: calc(100vh - 68px);
+  display: grid;
+  align-items: center;
+}
+
+.contact-title{
+  font-size: clamp(76px, 11vw, 152px);
+  letter-spacing: -0.04em;
+  line-height: 0.92;
+}
+
+.contact-links{
+  margin-top: 22px;
+  display: grid;
+  gap: 10px;
+  font-size: 16px;
+  color: rgba(26, 26, 26, 0.8);
+}
+
+.contact-links a{ width: fit-content; }
+
+/* Footer */
+.footer{
+  padding: 34px 0 56px;
+  color: var(--muted);
+  font-size: 13px;
+}
+
